/** Request for MigrateBookingsTimezone. */
export interface MigrateBookingsTimezoneRequest {
  /**
   * Metasite whose bookings are swept.
   * @format GUID
   */
  metaSiteId?: string;
  /**
   * Target tz-rules version to migrate to, e.g. "2026c".
   * @maxLength 16
   */
  targetVersion?: string;
  /**
   * Source (current) tz-rules version to recover the original local time against when a booking has
   * no localStartDate/offset. Optional; defaults to the pre-versioning baseline ("2023c") every
   * legacy booking was written under. Set it for a later migration whose source data was written
   * under a different version.
   * @maxLength 16
   */
  sourceVersion?: string;
  /**
   * Only sweep bookings whose slot ends after this instant (bounds the scan, e.g. now or the
   * zone's divergence date). Omit for no lower bound.
   */
  fromDate?: Date | null;
  /**
   * Only sweep bookings whose slot starts at or before this instant. With from_date this selects
   * bookings overlapping [from_date, to_date], letting a caller partition a site into windows.
   * Omit for no upper bound. Must not be before from_date.
   */
  toDate?: Date | null;
}

/** Response for MigrateBookingsTimezone. */
export interface MigrateBookingsTimezoneResponse {
  /** Number of bookings whose stored time diverged under target_version and was rewritten. */
  migratedCount?: number;
  /**
   * Number of bookings scanned by the sweep. Returned only on full success — if any booking
   * fails the sweep continues but the RPC returns a non-OK status, so callers cannot mistake a
   * partial run for a complete one (re-run is idempotent).
   */
  scannedCount?: number;
  /**
   * Number of bookings deliberately left unmigrated because their stored data can't be recomputed
   * exactly (e.g. a DST-straddling course whose summary needs authoritative per-session derivation).
   * A non-zero value means the sweep is not fully complete for those rows.
   */
  skippedCount?: number;
  /**
   * Number of cross-timezone slot bookings left unmigrated because migrating them would move the
   * customer's local time, which requires notifying them. They are fixed by a separate loud pass that
   * reschedules each against its migrated event; a non-zero value means that work is still owed.
   * @internal
   */
  crossTzSkippedCount?: number;
  /**
   * Number of slot bookings left unmigrated because their booked calendar-3 event is still on the old
   * rules. Expected mid-migration; a re-run after the events sweep clears them. A count that survives a
   * re-run means calendar-3 is deliberately holding those events back (cross-timezone), so those bookings
   * are owed the same loud pass.
   * @internal
   */
  unmigratedEventSkippedCount?: number;
}

